/* 字体结构体 */
const  ipgui_font_t open_sans_33px = {
    .glyphs = ( ipgui_glyph_t*)open_sans_33px_glyph_array,
    .line_height = 39,
    .baseline = 25,
    .font_size = 33,
    .max_height = 33,
    .space_width = 9
};

/* 获取字形函数 */
const  ipgui_glyph_t* open_sans_33px_get_glyph(unsigned char char_code)
{
    if (char_code < 128) {
        return &open_sans_33px_glyph_array[char_code];
    }
    return &open_sans_33px_char_063;  /* 返回'?'字符 */
}

/* 文本宽度计算 */
unsigned short open_sans_33px_text_width(const char* text)
{
    unsigned short width = 0;
    while (*text) {
        unsigned char ch = (unsigned char)*text;
        if (ch < 128) {
            const  ipgui_glyph_t* glyph = &open_sans_33px_glyph_array[ch];
            width += glyph->advance;
        }
        text++;
    }
    return width;
}
